// Block (composition) — dependency-free source display with clipboard action.
// Button owns interaction and look; Stack owns the header and vertical arrangement.
import type { Ref } from "react";
import { Button } from "../components/Button";
import { ScrollArea } from "../components/ScrollArea";
import { Stack } from "../layouts/Stack";
import "./CodeBlock.css";

export interface CodeBlockProps {
  /** Source text rendered verbatim. */
  code: string;
  /** Optional language label; no syntax highlighting is performed. */
  language?: string;
  /** Called after the source has been written to the clipboard. */
  onCopy?: () => void;
  className?: string;
  ref?: Ref<HTMLElement>;
}

export function CodeBlock({ code, language, onCopy, className, ref }: CodeBlockProps) {
  const copyCode = async () => {
    await navigator.clipboard.writeText(code);
    onCopy?.();
  };

  return (
    <Stack
      ref={ref}
      gap="2x-small"
      className={className ? `sd-codeblock ${className}` : "sd-codeblock"}
    >
      {/* usage: chrome — the code block's header bar */}
      <Stack direction="row" align="center" justify="between" gap="small" className="sd-codeblock__header">
        {language && (
          <span className="sd-codeblock__language sd-type-caption-medium">{language}</span>
        )}
        <Button
          type="button"
          variant="secondary"
          size="small"
          className="sd-codeblock__copy"
          onPress={() => void copyCode()}
        >
          Copy
        </Button>
      </Stack>
      {/* The `<pre>` used to be the scrollport with a hardcoded `tabIndex={0}`, which is the same
          rule stated in the wrong direction: a snippet that FITS then owns an inert tab stop and
          draws a focus ring on something that cannot scroll. ScrollArea measures instead, so the tab
          stop appears exactly when there is somewhere to go. */}
      <ScrollArea orientation="horizontal" className="sd-codeblock__scroll">
        <pre className="sd-codeblock__pre sd-type-code-medium">
          <code className="sd-codeblock__code">{code}</code>
        </pre>
      </ScrollArea>
    </Stack>
  );
}

/* CodeBlock.css — .sd-codeblock (Block)
   Arrangement only, plus horizontal overflow. */
.sd-codeblock {
  width: 100%;
}

.sd-codeblock__language,
.sd-codeblock__pre {
  margin: 0;
}

.sd-codeblock__copy {
  margin-inline-start: auto;
}

/* The scrollport is the ScrollArea around it, not this element. The `<pre>` must size to its own
   CONTENT so its border box is what grows: left at the container's width it would stay put while
   only its text overflowed, and the ResizeObserver watching it would never see the change. */
.sd-codeblock__scroll {
  min-width: 0;
  width: 100%;
}

.sd-codeblock__pre {
  width: max-content;
  min-width: 100%;
}
